import { type APIRequestContext } from '@playwright/test';
import { test, expect, type SectionEncounter } from '../../core';
import { HIV_INTAKE_ENCOUNTER_TYPE_UUID } from '../../core/constants';
import { SectionFormPage, ViewFormPage } from '../../pages';

// hiv/section-symptoms.xml: HIV signs and symptoms, 18 checkboxes (nausea ... epigastric pain) generated by a
// <repeat>; each is its own CIEL:1727 obsgroup holding one CIEL:1728 answer. Unreferenced (documentation/
// _availability.e2e.md): the specs open the edit URL directly on an HIV intake encounter.
//
// Conditions in the form, from documentation inventory (section-symptoms.inv.md): none besides
//   ifMode VIEW include=false  :4, :62   heading + script, and the #buttons row in ENTER/EDIT only
// Scripts: :14 setUpNextAndSubmitButtons() only (see _shared.e2e.md). No validation, message, default or derived value.
// Side effects on save: none. No required field.
// Visit-page display: the visit page never shows this form's own VIEW (no entry of encounterTypeConfig.js names it). The
//   symptom groups it saves (CIEL:1727 / 1728) are the ones section-hiv-assessment.xml shows (showIfEmpty=false), and the HIV
//   Intake entry (:1505) lists that section (`hiv-assessment`) with its VIEW. So the VIEW test asserts the ticked symptoms in the
//   VIEW of section-hiv-assessment.xml on the visit page; this form's own VIEW is therefore not tested.
// UNREACHABLE: no profile of this repo offers this form (documentation/_availability.e2e.md "Not reachable": not in
//   encounterTypeConfig.js, no <subform>). Tests open it by direct URL on an HIV intake encounter.
// Search scope: no reference found by name, formUuid or encounter type in pihcore, coreapps, htmlformentry(ui), registrationapp, pihemr and the zl/sl/liberia config repos; NOT searched: openmrs-module-mirebalais, the ADT/O2 modules, and the deployed server's app definitions / global properties. "Unreachable" here means not found, not proven.
// Not covered here: #next (needs the visit page).
//
// Findings:
//   V1 Info (form) the section is not offered anywhere (see _availability), so these checkboxes cannot be reached from the UI.

const FORM = 'hiv/section-symptoms.xml';

// Local helper: display of each obs on the (synthetic) encounter (group parents included).
const obsDisplays = async (api: APIRequestContext, encounterUuid: string): Promise<string[]> => {
  const res = await api.get(`obs?encounter=${encounterUuid}&v=custom:(display)&limit=100`);
  expect(res.ok()).toBeTruthy();
  return ((await res.json()).results as Array<{ display: string }>).map((o) => o.display);
};

test.describe('section-symptoms @unreachable', () => {
  let section: SectionEncounter;

  test.beforeEach(async ({ page, createSectionEncounter }) => {
    section = await createSectionEncounter({
      encounterTypeUuid: HIV_INTAKE_ENCOUNTER_TYPE_UUID,
      patient: { givenName: 'AutoSymptom', familyName: 'Tester', gender: 'M' },
    });
    await SectionFormPage.openEdit(page, FORM, section);
  });

  test('renders the 18 symptom checkboxes, none ticked', async ({ page }) => {
    // <repeat> :24-58 (18 <render>s)
    await expect(page.locator('.hiv-symptoms input[type=checkbox]')).toHaveCount(18);
    await expect(page.locator('.hiv-symptoms input[type=checkbox]:checked')).toHaveCount(0);
    for (const label of ['Nausea', 'Prurigo nodularis', 'Epigastric pain']) {
      await expect(page.getByLabel(label, { exact: true })).toBeVisible();
    }
  });

  test('saves the ticked symptoms, and EDIT shows only those ticked; unticking one removes it', async ({ page, api }) => {
    await page.getByLabel('Nausea', { exact: true }).check();
    await page.getByLabel('Fever', { exact: true }).check();
    await page.getByLabel('Prurigo nodularis', { exact: true }).check(); // CIEL:128321, missing from the mappings CSV
    await new SectionFormPage(page, FORM).save();
    await new SectionFormPage(page, FORM).expectSaved();

    const displays = (await obsDisplays(api, section.encounter.uuid)).map((d) => d.toLowerCase());
    for (const symptom of ['nausea', 'fever', 'prurigo']) {
      expect(displays.some((d) => d.includes(symptom)), symptom).toBeTruthy();
    }
    expect(displays.some((d) => d.includes('cough'))).toBeFalsy();

    await SectionFormPage.openEdit(page, FORM, section);
    await expect(page.locator('.hiv-symptoms input[type=checkbox]:checked')).toHaveCount(3);
    await expect(page.getByLabel('Fever', { exact: true })).toBeChecked();

    await page.getByLabel('Fever', { exact: true }).uncheck();
    await new SectionFormPage(page, FORM).save();
    await new SectionFormPage(page, FORM).expectSaved();
    const after = (await obsDisplays(api, section.encounter.uuid)).map((d) => d.toLowerCase());
    expect(after.some((d) => d.includes('fever'))).toBeFalsy();
    expect(after.some((d) => d.includes('nausea'))).toBeTruthy();
  });

  // Visit-page display: the HIV Intake entry's hiv-assessment section shows the ticked symptoms (its form lists them
  // from the same obs groups) and no unticked one.
  test('the visit page shows the ticked symptoms in the hiv-assessment section, and no other', async ({ page }) => {
    await page.getByLabel('Nausea', { exact: true }).check();
    await page.getByLabel('Fever', { exact: true }).check();
    await new SectionFormPage(page, FORM).save();
    await new SectionFormPage(page, FORM).expectSaved();

    const view = await ViewFormPage.open(page, 'hiv/section-hiv-assessment.xml', section.encounter.uuid);
    expect(await view.valueTexts()).toEqual(['[X] Nausea', '[X] Fever']);
    await expect(view.root.getByText('Cough')).toHaveCount(0);
    await expect(view.root.getByText('Vomiting')).toHaveCount(0);
  });
});
